{"path":"src/core/battle.ts","content":"import { Card, DeckManager } from './deck';

export interface Character {
  id: string;
  name: string;
  hp: number;
  maxHp: number;
  ap: number;
  maxAp: number;
}

export class BattleManager {
  deckManager: DeckManager;
  characters: Map<string, Character> = new Map();
  currentAp: number = 3;
  maxAp: number = 3;

  constructor(characters: Character[], initialCards: Card[]) {
    characters.forEach(c => this.characters.set(c.id, c));
    this.deckManager = new DeckManager(initialCards);
  }

  startTurn(): void {
    this.currentAp = this.maxAp;
    this.deckManager.draw(5);
  }

  playCard(cardId: string): boolean {
    const cardIndex = this.deckManager.hand.findIndex(c => c.id === cardId);
    if (cardIndex === -1) return false;

    const card = this.deckManager.hand[cardIndex];
    if (this.currentAp < card.cost) return false;

    this.currentAp -= card.cost;
    this.deckManager.discardCard(cardId);
    return true;
  }

  endTurn(): void {
    this.deckManager.endTurn();
    this.startTurn();
  }
}
