import { EquipmentSlot, Equipment, StatModifiers, Trait, CharacterEquipmentManager } from './equipment';

export interface PartySynergyRule {
  tag: string;
  requiredCount: number;
  bonusModifiers: StatModifiers;
  description: string;
}

export class PartySynergySystem {
  private rules: PartySynergyRule[] = [];

  public registerRule(rule: PartySynergyRule): void {
    this.rules.push(rule);
  }

  public evaluateSynergies(managers: CharacterEquipmentManager[]): { activeRules: PartySynergyRule[]; totalBonus: StatModifiers } {
    const tagCounts: Record<string, number> = {};

    for (const manager of managers) {
      const tags = manager.getActiveSynergyTags();
      for (const tag of tags) {
        tagCounts[tag] = (tagCounts[tag] || 0) + 1;
      }
    }

    const activeRules: PartySynergyRule[] = [];
    const totalBonus: StatModifiers = { hp: 0, attack: 0, defense: 0, speed: 0, critRate: 0, critDamage: 0 };

    for (const rule of this.rules) {
      const count = tagCounts[rule.tag] || 0;
      if (count >= rule.requiredCount) {
        activeRules.push(rule);
        for (const [key, val] of Object.entries(rule.bonusModifiers)) {
          const k = key as keyof StatModifiers;
          totalBonus[k] = (totalBonus[k] || 0) + (val || 0);
        }
      }
    }

    return { activeRules, totalBonus };
  }
}

