export interface StatModifiers {
  hp?: number;
  attack?: number;
  defense?: number;
  speed?: number;
  critRate?: number;
  critDamage?: number;
}

export interface Equipment {
  id: string;
  name: string;
  slot: EquipmentSlot;
  modifiers: StatModifiers;
  effectDescription: string;
  passiveId?: string;
}

export interface Trait {
  id: string;
  name: string;
  description: string;
  modifiers: StatModifiers;
  synergyTags: string[];
}

export class CharacterEquipmentManager {
  private slots: Record<EquipmentSlot, Equipment | null> = {
    weapon: null,
    armor: null,
    accessory: null,
  };
  private traits: Trait[] = [];

  public equip(equipment: Equipment): void {
    this.slots[equipment.slot] = equipment;
  }

  public unequip(slot: EquipmentSlot): Equipment | null {
    const prev = this.slots[slot];
    this.slots[slot] = null;
    return prev;
  }

  public addTrait(trait: Trait): void {
    if (!this.traits.some(t => t.id === trait.id)) {
      this.traits.push(trait);
    }
  }

  public removeTrait(traitId: string): void {
    this.traits = this.traits.filter(t => t.id !== traitId);
  }

  public getTotalModifiers(): StatModifiers {
    const total: StatModifiers = { hp: 0, attack: 0, defense: 0, speed: 0, critRate: 0, critDamage: 0 };

    // Equipment
    for (const slot of Object.keys(this.slots) as EquipmentSlot[]) {
      const eq = this.slots[slot];
      if (eq) {
        for (const [key, val] of Object.entries(eq.modifiers)) {
          const k = key as keyof StatModifiers;
          total[k] = (total[k] || 0) + (val || 0);
        }
      }
    }

    // Traits
    for (const trait of this.traits) {
      for (const [key, val] of Object.entries(trait.modifiers)) {
        const k = key as keyof StatModifiers;
        total[k] = (total[k] || 0) + (val || 0);
      }
    }

    return total;
  }

  public getActiveSynergyTags(): string[] {
    const tags: string[] = [];
    for (const trait of this.traits) {
      tags.push(...trait.synergyTags);
    }
    return Array.from(new Set(tags));
  }
}
